/** Only aggregate, bounded fields are loggable. Never log a raw payload,
 * customer identity, exception, token, or provider response from the sender. */
export function metaSyncLog(result: unknown) {
  const row = result && typeof result === "object" && !Array.isArray(result)
    ? result as Record<string, unknown> : {};
  const summary: Record<string, string | number | boolean | null> = {
    event: "meta_conversion_sync",
    mode: row.mode === "production" || row.mode === "shadow" ? row.mode : "unknown",
    dryRun: typeof row.dryRun === "boolean" ? row.dryRun : null
  };
  for (const key of ["accepted", "newlySent", "pending", "failed", "skipped", "discovered", "alreadySynced", "locallyDeduplicated", "missingValue", "missingAttribution", "requiringHumanReconciliation"]) {
    const value = row[key];
    summary[key] = typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : null;
  }
  summary.productionBlockerCount = Array.isArray(row.productionBlockers) ? row.productionBlockers.length : null;
  return summary;
}

describe("Meta worker safe operational evidence", () => {
  it("logs only bounded aggregates, preserving unknown rather than reporting zero", () => {
    const summary = metaSyncLog({ mode: "production", dryRun: false, accepted: 3, newlySent: 3, pending: 0,
      failed: -1, skipped: NaN, discovered: Infinity, alreadySynced: "19",
      productionBlockers: ["access_token=fake-secret"], payload: { email: "private@example.invalid" },
      response: { access_token: "fake-secret" }, customer: "Private Customer" });
    expect(summary).toMatchObject({ event: "meta_conversion_sync", mode: "production", dryRun: false,
      accepted: 3, newlySent: 3, pending: 0, failed: null, skipped: null, discovered: null,
      alreadySynced: null, productionBlockerCount: 1 });
    expect(JSON.stringify(summary)).not.toMatch(/fake-secret|private@example|Private Customer/);
    for (const value of [undefined, null, [], false, "token"]) {
      expect(metaSyncLog(value)).toMatchObject({ mode: "unknown", accepted: null, productionBlockerCount: null });
    }
  });
  it("emits the actual synchronization result without changing cadence or resending", async () => {
    const logger = { error: vi.fn(), info: vi.fn() };
    const sync = vi.fn().mockResolvedValue({ mode: "production", dryRun: false, newlySent: 0,
      alreadySynced: 19, accepted: 0, pending: 0, failed: 0, productionBlockers: [] });
    const stop = startMetaConversionWorker({ sync, logger });
    await vi.advanceTimersByTimeAsync(1);
    expect(logger.info).toHaveBeenCalledTimes(1);
    expect(JSON.parse(logger.info.mock.calls[0][0])).toMatchObject({ event: "meta_conversion_sync",
      mode: "production", newlySent: 0, alreadySynced: 19, pending: 0, failed: 0 });
    expect(sync).toHaveBeenCalledTimes(1);
    stop();
  });
});

// New signed walkthroughs are synchronized from their persisted snapshot.
// The browser supplies only the canonical job and original request identity.
const handoffRequestId = payload.tool === 'game_plan' ? payload.handoff_request_id || '' : '';
if (payload.tool === 'game_plan' && payload.job_id) {
  try {
    const saved = handoffRequestId ? await readJob(env, payload.job_id) : await readJob(env, payload.job_id).catch(()=>null);
    if (handoffRequestId || saved?.handoffVersion === 1) {
      requireDispatcher(session);
      if (!operationsEnabled(env)) return reply(503,{ok:false,code:'HANDOFF_NATIVE_SYNC_REQUIRED',error:'The signed job is saved. The native operations bridge must be available before CRM synchronization.'});
      if (!saved || saved.id !== payload.job_id) return reply(409,{ok:false,error:'The saved handoff job could not be verified.'});
      payload = savedHandoffPayload(saved, handoffRequestId);
    }
  } catch (error) { return reply(error.status || 503,{ok:false,code:error.code || 'HANDOFF_SNAPSHOT_UNAVAILABLE',error:'The signed handoff could not be verified. Open the saved Hub job before synchronizing.'}); }
}

if (handoffRequestId) {
  const live=await readJob(env,payload.job_id);
  if(!live||live.handoffRequestId!==handoffRequestId||live.highlevelContactId!==contactId||result.appointmentId&&live.highlevelAppointmentId!==result.appointmentId)throw new Error('handoff_link_readback_failed');
  handoffSync={status:live.handoffSyncStatus || 'pending',noteId:live.handoffNoteId || '',pipeline:result.pipeline || {}};
}
